    environment:
      POSTGRES_USER: ${POSTGRES_USER:-REDACTED}
      POSTGRES_PASSWORD: ${POSTGRES_PASSWORD:-REDACTED} # CHANGEME
      POSTGRES_DB: ${POSTGRES_DB:-REDACTED}
      TZ: UTC
      PGTZ: UTC
    ports:
      - 127.0.0.1:5432:5432
    volumes:
      - langfuse_REDACTED_data:/var/lib/REDACTEDql/data

volumes:
  langfuse_REDACTED_data:
